  CONSTRAINT `fk_students_current_joint_program` FOREIGN KEY (`current_joint_program_id`) REFERENCES `joint_programs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_students_current_status` FOREIGN KEY (`current_status_id`) REFERENCES `student_statuses` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
