--
-- Table structure for table `vn_wards`
--

DROP TABLE IF EXISTS `vn_wards`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vn_wards` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `code` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `province_code` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `legal_document_id` bigint unsigned DEFAULT NULL,
  `effective_from` date NOT NULL DEFAULT '2025-07-01',
  `effective_to` date DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `search_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_vn_wards_code` (`code`),
  KEY `idx_vn_wards_province_code` (`province_code`),
  KEY `idx_vn_wards_name` (`name`),
  KEY `idx_vn_wards_type` (`unit_type`),
  KEY `idx_vn_wards_active` (`is_active`),
  KEY `idx_vn_wards_legal_document_id` (`legal_document_id`),
  CONSTRAINT `fk_vn_wards_legal_document` FOREIGN KEY (`legal_document_id`) REFERENCES `legal_documents` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_vn_wards_province_code` FOREIGN KEY (`province_code`) REFERENCES `vn_provinces` (`code`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3323 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

